"""
patch_L322_4_mechanism_20260916.py -- ORRERY repo. L-322, the mechanism,
orrery half (pieces 1 to 5 and 7 of
documentation/BUILD_MANIFEST_L322_mechanism_20260916.md).

Built on 6b282b2e4f1223a83f0d71145c60cdda5cd10094
at https://github.com/tonylquintanilla/palomas_orrery

RUN
---
Save this file in the orrery repo root, beside constants_new.py. Open it
in VS Code and click Run.

    python patch_L322_4_mechanism_20260916.py

WHAT IT DOES -- all or nothing
------------------------------
Creates five new files:
    constants_tokens.py        what each "# Unit:" token means
    constants_rows.py          the one shared reader of constants_new.py
    export_constants.py        writes data/constants_export.json
    test_constants_export.py   checks the export matches the store
    test_dimensions.py         checks each derived row's unit
Replaces one file:
    test_derived_figures.py    rewritten to Rule 8
Edits three files:
    orrery_maintenance_run.py  one new generator, two new checkers
    palomas_orrery_dashboard.py  three new buttons, one new description
    LEDGER_CONSOLIDATED.md     a build note on L-322, a line on L-325
It does NOT touch constants_new.py.

Every file is checked before anything is written. If any check fails,
NOTHING is written, and the output says which check failed. A second run
refuses, because the files it creates already exist.

SUCCESS looks like one "ok" line per file, then "patch applied".
Then, in this order:
    1. Move this script into documentation/ -- before the maintenance
       run, so the generated documents do not count it as a module.
    2. python ledger_index.py LEDGER_CONSOLIDATED.md   (twice; OK: 330)
    3. python orrery_maintenance_run.py
       It creates data/constants_export.json and runs the new checkers.
       test_dimensions.py needs astropy, which requirements.txt lists.

UNDO: Discard Changes in GitHub Desktop, and delete the five new files
it lists as untracked.

WHAT IS PERMANENT: the five new modules, the rewritten checker, the
runner and dashboard rows, and the ledger text. This script is spent
after one run.

Role: patch
Domain: dev_tools

Written September 16, 2026 with Anthropic's Claude Opus 5.
"""

