LEDGER_ZONE = (b"<!-- INDEX:START", b"<!-- INDEX:END -->")


def lf(data):
    return data.replace(b"\r\n", b"\n")


def md5_content(data):
    return hashlib.md5(lf(data)).hexdigest()


def ledger_fingerprint(data):
    data = lf(data)
    start = data.index(LEDGER_ZONE[0])
    end = data.index(LEDGER_ZONE[1]) + len(LEDGER_ZONE[1])
    return hashlib.md5(data[:start] + data[end:]).hexdigest()


def decode(name, sha, b64):
    data = base64.b64decode("".join(b64))
    if hashlib.sha256(data).hexdigest() != sha:
        raise SystemExit("ERROR: the embedded copy of %s is damaged "
                         "(checksum mismatch). NOTHING was written." % name)
    return data


def apply_edits(path, data, edits):
    was_crlf = b"\r\n" in data
    text = lf(data).decode("utf-8")
    for old, new in edits:
        count = text.count(old)
        if count != 1:
            raise SystemExit("ANCHOR FAIL in %s: expected 1 match, found %d "
                             "for: %r\nNOTHING was written."
                             % (path, count, old[:70]))
        text = text.replace(old, new)
    out = text.encode("utf-8")
    if was_crlf:
        out = out.replace(b"\n", b"\r\n")
    return out, was_crlf


def main():
    here = os.path.dirname(os.path.abspath(__file__))
    os.chdir(here)
    if not os.path.exists("constants_new.py"):
        raise SystemExit("ERROR: this script is not in the orrery repo root "
                         "(no constants_new.py beside it). NOTHING was "
                         "written.")

    planned = []

    for name, sha, b64 in NEW_FILES:
        if os.path.exists(name):
            raise SystemExit("ERROR: %s already exists -- this patch has "
                             "already run, or a file of that name is in the "
                             "way. NOTHING was written." % name)
        planned.append((name, decode(name, sha, b64), "created", False))

    name, sha, b64 = REWRITE
    with open(name, "rb") as handle:
        old = handle.read()
    if md5_content(old) != fingerprints()[name]:
        raise SystemExit("ERROR: %s is not the version this patch was built "
                         "on (6b282b2e). NOTHING was written." % name)
    new = decode(name, sha, b64)
    if b"\r\n" in old:
        new = new.replace(b"\n", b"\r\n")
    planned.append((name, new, "rewritten", b"\r\n" in old))

    for path, edits in (("orrery_maintenance_run.py", RUNNER_EDITS),
                        ("palomas_orrery_dashboard.py", DASH_EDITS),
                        ("LEDGER_CONSOLIDATED.md", LEDGER_EDITS)):
        with open(path, "rb") as handle:
            data = handle.read()
        if path == "LEDGER_CONSOLIDATED.md":
            actual = ledger_fingerprint(data)
        else:
            actual = md5_content(data)
        if actual != fingerprints()[path]:
            raise SystemExit("ERROR: %s is not the version this patch was "
                             "built on (6b282b2e). NOTHING was written."
                             % path)
        out, was_crlf = apply_edits(path, data, edits)
        planned.append((path, out, "edited (%d changes)" % len(edits),
                        was_crlf))

    for path, data, _what, _crlf in planned:
        try:
            lf(data).decode("ascii")
        except UnicodeDecodeError:
            raise SystemExit("ERROR: %s would contain non-ASCII text. "
                             "NOTHING was written." % path)

    # Every check passed. Write.
    for path, data, what, was_crlf in planned:
        with open(path, "wb") as handle:
            handle.write(data)
        print("ok  %-30s %s%s" % (path, what,
                                  " [CRLF kept]" if was_crlf else ""))

    total = sum(len(data) for _p, data, _w, _c in planned)
    print("")
    print("Stamps updated: the docstrings of orrery_maintenance_run.py and")
    print("palomas_orrery_dashboard.py; the rewritten test_derived_figures.py")
    print("carries its own. The five new modules are stamped as created.")
    print("")
    print("STILL SAYS SOMETHING NOW FALSE, not edited here: constants_new.py,")
    print("in its module docstring's L-325 paragraph and in the Notes of")
    print("EARTH_MAGNETOPAUSE_STANDOFF_RADII and EARTH_BOW_SHOCK_STANDOFF_RADII,")
    print("says test_derived_figures.py recomputes those two rows. It no longer")
    print("does. The Earth-slice visit that reverts both rows rewrites those Notes.")
    if importlib.util.find_spec("astropy") is None:
        print("")
        print("NOTE: astropy is not installed in this Python. test_dimensions.py")
        print("needs it; it is listed in requirements.txt.")
    print("")
    print("patch applied (%d bytes across %d files)" % (total, len(planned)))
    print("Next: move this script into documentation/, then run")
    print("python ledger_index.py LEDGER_CONSOLIDATED.md twice, then")
    print("python orrery_maintenance_run.py.")
    return 0


if __name__ == "__main__":
    sys.exit(main())
